/**
 * SilicoTrack service worker.
 *
 * The offline claim in this project is load-bearing, so this file is
 * deliberately small enough to reason about in one sitting rather than
 * generated by a plugin.
 *
 * Strategy:
 *   - Navigations: network first, cache fallback. A worker with signal gets
 *     the current app; a worker in a quarry gets the last one that loaded.
 *   - Static assets (JS/CSS/fonts/icons): cache first. These are content
 *     hashed by Next, so a cached copy is never stale.
 *   - /api/sync: NEVER cached, NEVER intercepted. A queued interview must
 *     reach the real server or be reported as failed so the outbox retries.
 *     Serving a cached 200 here would silently drop a worker's record.
 */

const VERSION = 'silicotrack-v1';
const SHELL = `${VERSION}-shell`;
const ASSETS = `${VERSION}-assets`;

/** Enough to boot the interview with no network at all. */
const SHELL_URLS = ['/field', '/manifest.webmanifest', '/icon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(SHELL);
      // Individually, so one 404 cannot fail the whole install.
      await Promise.all(
        SHELL_URLS.map((url) => cache.add(url).catch(() => undefined)),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys.filter((key) => !key.startsWith(VERSION)).map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    })(),
  );
});

function isStaticAsset(url) {
  return (
    url.pathname.startsWith('/_next/static/') ||
    url.pathname.startsWith('/icon') ||
    /\.(?:css|js|woff2?|svg|png|ico)$/.test(url.pathname)
  );
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Sync must always hit the network. See the note at the top of this file.
  if (url.pathname.startsWith('/api/')) return;

  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const response = await fetch(request);
          const cache = await caches.open(SHELL);
          cache.put(request, response.clone());
          return response;
        } catch {
          const cached = await caches.match(request);
          if (cached) return cached;
          const shell = await caches.match('/field');
          if (shell) return shell;
          return new Response(
            '<!doctype html><meta charset="utf-8"><title>SilicoTrack</title>' +
              '<p style="font:600 18px system-ui;padding:24px">' +
              'ऑफ़लाइन — यह पृष्ठ अभी उपलब्ध नहीं है।<br>Offline — this page is not cached yet.</p>',
            { status: 503, headers: { 'content-type': 'text/html; charset=utf-8' } },
          );
        }
      })(),
    );
    return;
  }

  if (isStaticAsset(url)) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request);
        if (cached) return cached;
        const response = await fetch(request);
        if (response.ok) {
          const cache = await caches.open(ASSETS);
          cache.put(request, response.clone());
        }
        return response;
      })(),
    );
  }
});
